;*******************************************;BC POS INITIALISIERUNG AB ADR 1000H;*******************************************;;REVISION 4.3  19.12.86;*I POS.TYP	ORG	1000H;STACK	EQU	0D00H;	LD	SP,STACK;;-----------------------------------------------;LAUFWERKSINITIALISIERUNG	EXTERNAL FLINTR;	LD	A,0FFh	;BITMODE	OUT	(FSPBC),A	LD	A,0F3h	OUT	(FSPBC),A	LD	A,7Fh	;InPutmoDE	OUT	(FDPBC),A	LD	A,3Fh	OUT	(FSPAC),a	;OutputmoDE	OUT	(FDPAC),a	LD	A,0E0h	;IV Low-Teil	OUT	(CTC),A	LD	A,37H	OUT	(CTC+2),A	LD	A,192	;20mS	OUT	(CTC+2),A	XOR	A	LD	(ADRNR),A	LD	L,A	LD	H,A	LD	(IOVA),HL	LD	(SPNRL),HL	LD	(SPNRL+2),HL	LD	HL,FLINTR	LD	(FDIV),HL;SFDT	LD	A,(3FCH)	;TEST SYL-FD	LD	B,-1IM0	INC	B	RRCA	JR	C,IM0IM1	LD	A,B	RRCA	RRCA	RRCA	LD	(OSDISK),A;;-----------------------------------------------;	LD	BC,0C00H	;PROM UMSPEICHERN	LD	D,C	LD	E,C	LD	HL,1100H	LDIR;;-----------------------------------------------;	LD	E,4	;TEST VORHANDENER FD	LD	A,77h	EXX	LD	HL,DISCON	LD	BC,FDC01	LD	DE,FDC23	EXXIM4	RLCA	OUT	(I12),A	EX	AF,AF'	LD	B,78IM5	LD	A,5Fh	OUT	(FSPAD),A	LD	A,0DFh	OUT	(FSPAD),A	IN	A,(FSPBD)	RLCA	JR	C,IM6;LW VORHANDEN	LD	A,-1FD	EXX	AND	C	LD	(HL),A	INC	HL	LD	C,B	LD	B,E	LD	E,D	EXX	DEC	E	JR	Z,IM7	EX	AF,AF'	JR	IM4IM6	LD	H,8	DEC	L	JR	NZ,$-1	DEC	H	JR	NZ,$-4	DJNZ	IM5;LW NICHT VORHANDEN	XOR	A	JR	FD;LW'S ABSCHALTENIM7	LD	A,0FFh	OUT	(I12),A;CTC	EQU	0CHFSPAD	EQU	10HFSPAC	EQU	11HFSPBD	EQU	12HFSPBC	EQU	13HFDPAC	EQU	15HFDPBC	EQU	17HI12	EQU	18H;DISCON	EQU	0BE1HOSDISK	EQU	0EDCHFDIV	EQU	0FE6HSPNRL	EQU	0FCEhIOVA	EQU	0FC7HADRNR	EQU	0EDDH;;-----------------------------------------------;TASTATURINITIALISIEREN;TYPEN TT=;1=7606 2=7636 3=7604 4=7634 5=7637;	LD	A,6FH	;DRUCK EI, INS ON	LD	(TSB),A	LD	A,7FH	LD	(TSB2),A;TSB2	EQU	0FDAHTSB	EQU	0FDBH;;IFSS-TASTATUR	COND	TT=5	EXTERNAL  TP	LD	HL,ITHW	LD	BC,200H+DUCTC	OTIR	LD	BC,600H+DUSBC	OTIR	XOR	A	OUT	(DUSBD),ATZS	DEC	C	JR	NZ,TZS	DJNZ	TZS	IN	A,(DUSBD)	AND	0F0H	SUB	80H	JR	Z,TIEND	LD	HL,ITHW	LD	BC,200H+DRCTC	OTIR	LD	BC,600H+DRSAC	OTIR	XOR	A	OUT	(DRSAD),A	LD	A,DRSAD	LD	(TP+1),A;;DFUE PORTS:DUCTC	EQU	59HDUSBD	EQU	52HDUSBC	EQU	53H;ZUSATSDRUCKERPORTSDRCTC	EQU	058HDRSAC	EQU	05DHDRSAD	EQU	05CHTIEND	ENDC;-----------------------------------------------;BILDSCHIRMINITIALISIEREN	LD	A,BWSA.SHR.8	LD	(BWS),A	LD	(MADR+1),A	LD	A,ERA	CALL	OUTA;ERA	EQU	1FHOUTA	EQU	0BEBHBWS	EQU	0FD7HMADR	EQU	0FDEH;-----------------------------------------------;DRUCKER INITIALISIEREN;TYPEN DT=;0=KEINER 1=PIO 2=IFSS 3=ZIFSS 4=V24 5=1156 (SIF1000);	COND	DT=0	RST	0	ENDC;	COND DT=1;PIO II;	EXTERNAL WRINT;	LD	HL,WRINT	LD	(DRIV),HL	LD	A,8FH		OUT	(PAC),A	LD	A,DRIV&00FFH	OUT	(PBC),A	LD	A,7FH	OUT	(PBC),A	OUT	(PBD),A	LD	A,0FFH	OUT	(PBC),A	DEC	A	OUT	(PBC),A	OUT	(PBD),A	IN	A,(PAD)	LD	A,87H	OUT	(PBC),A	XOR	A	OUT	(PAD),A	RST	0;DRIV	EQU	0FF0H;PAD	EQU	54HPAC	EQU	55HPBD	EQU	56HPBC	EQU	57H	ENDC;	COND	(DT=2).OR.(DT=3);IFSS ZIFSS	LD	HL,IDHW	LD	BC,200H+DCTC	OTIR	LD	BC,600H+DSC	OTIR	XOR	A	OUT	(DSD),A	RST	0;IDHW	DEFB	7	DEFB	1;	DEFB	4	DEFB	4DH	DEFB	3	DEFB	41H	DEFB	5	DEFB	28H;	COND	DT=2;IFSS HAUPTDRUCKERDCTC	EQU	58HDSD	EQU	5EHDSC	EQU	5FH	ENDC;	COND	DT=3;IFSS ZUSATZDRUCKERDCTC	EQU	58HDSD	EQU	5CHDSC	EQU	5DH	ENDC;	ENDC;	COND	DT=4;V24	LD	HL,IDHW	LD	BC,200H+DCTC	OTIR	LD	BC,600H+DSC	OTIR	XOR	A	OUT	(DSD),A	RST	0;IDHW	DEFB	7	DEFB	9600/V;	DEFB	4	DEFB	4CH	DEFB	3	DEFB	41H	DEFB	5	DEFB	0E8H;V	EQU	9600	;BOUDRATEDCTC	EQU	0CHDSD	EQU	50HDSC	EQU	51H	ENDC;	COND	DT=5;1156PAD	EQU	70HPBD	EQU	71HPAC	EQU	72HPBC	EQU	73H;	EXTERNAL WRINT;	LD	HL,WRINT	LD 	(DRIV),HL	LD 	A,DRIV&00FFH	OUT	(PAC),A	LD	A,0FH	OUT	(PAC),A	LD	A,87H	OUT	(PAC),A	LD	A,1CH	OUT	(PAD),A	LD	A,19H	OUT	(PAD),A	IN	A,(PBD)	LD	A,0DH	OUT	(PAD),A	RST	0;DRIV	EQU	0FF0H;	ENDC;;------------------------------------;IFSS TASTATUR	COND	TT=5ITHW	DEFB	7	DEFB	1;	DEFB	4	DEFB	44H	DEFB	5	DEFB	68H	DEFB	3	DEFB	0C1H;	ENDC